(function () {
  var run = function () {
    var blocks = document.querySelectorAll(".e-con.e-parent:not(.e-lazyloaded)");
    var watcher = new IntersectionObserver(function (entries) {
      entries.forEach(function (entry) {
        if (entry.isIntersecting) {
          entry.target.classList.add("e-lazyloaded");
          watcher.unobserve(entry.target);
        }
      });
    }, { rootMargin: "200px 0px 200px 0px" });
    blocks.forEach(function (b) { watcher.observe(b); });
  };
  ["DOMContentLoaded", "elementor/lazyload/observe"].forEach(function (e) { document.addEventListener(e, run); });
})();;
(function () {
  var text = {
    sent: "Your submission was successful.",
    failed: "Sorry, your message could not be sent right now. Please try again in a few minutes."
  };

  function say(form, kind, message) {
    var old = form.querySelector(".elementor-message");
    if (old) old.parentNode.removeChild(old);
    var box = document.createElement("div");
    box.className = "elementor-message elementor-message-" + kind;
    box.setAttribute("role", "alert");
    box.textContent = message;
    form.appendChild(box);
  }

  function collect(form) {
    var data = new FormData();
    Array.prototype.forEach.call(form.querySelectorAll(".elementor-field-group"), function (group) {
      var input = group.querySelector("input:not([type=hidden]):not([type=submit]), select, textarea");
      if (!input || !input.name) return;
      var label = group.querySelector("label");
      var key = input.type === "email" ? "email" : (label ? label.textContent.trim() : input.name);
      data.append(key, String(input.value || "").trim());
    });
    data.append("_subject", "New message from the website (" + document.title.split(" \u2013 ")[0] + ")");
    data.append("Sent from page", document.title + " - " + location.href.split("#")[0]);
    return data;
  }

  document.addEventListener("submit", function (event) {
    var form = event.target;
    if (!form.matches || !form.matches("form.elementor-form")) return;
    event.preventDefault();
    event.stopImmediatePropagation();
    if (form.classList.contains("elementor-form-waiting")) return;
    var button = form.querySelector("button[type=submit]");
    if (!FORMSPREE_URL) { say(form, "danger", text.failed); return; }
    form.classList.add("elementor-form-waiting");
    if (button) button.disabled = true;
    fetch(FORMSPREE_URL, { method: "POST", body: collect(form), headers: { Accept: "application/json" } })
      .then(function (response) {
        if (!response.ok) throw new Error("failed");
        form.reset();
        say(form, "success", text.sent);
      })
      .catch(function () { say(form, "danger", text.failed); })
      .then(function () {
        form.classList.remove("elementor-form-waiting");
        if (button) button.disabled = false;
      });
  }, true);
})();
